// Created: 2026-08-09

/**
 * Minimal gitignore-syntax matcher (#3315).
 *
 * `src/hooks` ships with ZERO runtime dependencies (see package.json — only
 * devDependencies), so the `ignore` npm package CC itself uses is not
 * available to us. This is a hand-rolled subset covering the syntax that
 * `.worktreeinclude` realistically uses:
 *
 *   - blank lines and `#` comments are skipped (`\#` escapes a literal `#`)
 *   - `!pattern` negates a previous match (last matching rule wins)
 *   - a leading `/` anchors the pattern to the repo root
 *   - a pattern containing `/` anywhere but the end is anchored to the root;
 *     one with no `/` matches at any depth
 *   - a trailing `/` restricts the match to directories
 *   - `*` matches within one segment, `?` matches one non-`/` char,
 *     `**` spans segments (`a/**`+`/b`, leading `**​/`, trailing `/**`)
 *   - `[...]` character classes, including `!`/`^` negation and the common
 *     POSIX classes
 *   - trailing whitespace is stripped unless backslash-escaped
 *
 * NOT covered (documented divergence): git's `core.excludesFile` layering,
 * per-directory `.gitignore` precedence, and case-insensitive matching on
 * case-folding filesystems. `.worktreeinclude` is a single root-level file so
 * the first two never apply; the third makes us stricter, never looser.
 *
 * A pattern that cannot be compiled matches NOTHING and is reported to the
 * caller rather than thrown — CC 2.1.207 fixed exactly this class of bug
 * ("malformed bracket patterns ... breaking ... worktree creation").
 */

interface Rule {
  re: RegExp;
  negate: boolean;
  dirOnly: boolean;
  source: string;
}

export interface GitignoreMatcher {
  /**
   * True when `path` (repo-relative, POSIX separators, no leading `/`) is
   * matched. A path is matched when it, or any ancestor directory, is matched
   * by a positive rule and not re-included by a later negative one.
   */
  ignores(path: string, isDir?: boolean): boolean;
  /** Patterns that failed to compile — they match nothing. */
  readonly invalidPatterns: readonly string[];
}

const REGEX_SPECIAL = /[.+^${}()|\\]/;

function escapeLiteral(ch: string): string {
  return REGEX_SPECIAL.test(ch) || ch === '[' || ch === ']' || ch === '*' || ch === '?'
    ? `\\${ch}`
    : ch;
}

const POSIX_CLASSES: Record<string, string> = {
  alpha: 'a-zA-Z',
  digit: '0-9',
  alnum: 'a-zA-Z0-9',
  lower: 'a-z',
  upper: 'A-Z',
  space: ' \\t\\r\\n\\v\\f',
  blank: ' \\t',
  xdigit: '0-9a-fA-F',
  word: '\\w',
  punct: '!-/:-@\\[-`{-~',
};

/** Translate a bracket expression starting at `p[i] === '['`. */
function translateClass(p: string, i: number): { source: string; next: number } | null {
  let j = i + 1;
  let negated = false;
  if (p[j] === '!' || p[j] === '^') {
    negated = true;
    j++;
  }
  let body = '';
  // A `]` immediately after the (optional) negation is a literal.
  if (p[j] === ']') {
    body += '\\]';
    j++;
  }
  while (j < p.length && p[j] !== ']') {
    if (p[j] === '\\') {
      body += `\\${p[j + 1] ?? '\\'}`;
      j += 2;
      continue;
    }
    if (p[j] === '[' && p[j + 1] === ':') {
      const end = p.indexOf(':]', j + 2);
      if (end === -1) {
        body += '\\[';
        j++;
        continue;
      }
      body += POSIX_CLASSES[p.slice(j + 2, end)] ?? '';
      j = end + 2;
      continue;
    }
    // `^` inside the body (not leading) is a literal; `-` keeps range meaning.
    body += p[j] === '^' ? '\\^' : p[j];
    j++;
  }
  if (j >= p.length) return null; // unterminated — caller falls back to literal
  return { source: `[${negated ? '^' : ''}${body}]`, next: j + 1 };
}

/** Translate a (already unanchored, already de-suffixed) glob to regex source. */
function translateGlob(p: string): string {
  let out = '';
  let i = 0;
  while (i < p.length) {
    const ch = p[i];

    if (ch === '\\') {
      const next = p[i + 1];
      if (next === undefined) {
        out += '\\\\';
        i++;
        continue;
      }
      out += escapeLiteral(next);
      i += 2;
      continue;
    }

    if (ch === '*') {
      if (p[i + 1] === '*') {
        const afterIdx = i + 2;
        const atSegmentStart = i === 0 || p[i - 1] === '/';
        if (atSegmentStart && p[afterIdx] === '/') {
          // `**/` — zero or more leading directories.
          out += '(?:[^/]+/)*';
          i = afterIdx + 1;
          continue;
        }
        if (atSegmentStart && afterIdx >= p.length) {
          // trailing `**` — everything below.
          out += '.*';
          i = afterIdx;
          continue;
        }
        // `**` glued to other chars degrades to `*`, matching git.
        out += '[^/]*';
        i = afterIdx;
        continue;
      }
      out += '[^/]*';
      i++;
      continue;
    }

    if (ch === '?') {
      out += '[^/]';
      i++;
      continue;
    }

    if (ch === '[') {
      const cls = translateClass(p, i);
      if (cls === null) {
        out += '\\[';
        i++;
        continue;
      }
      out += cls.source;
      i = cls.next;
      continue;
    }

    out += escapeLiteral(ch);
    i++;
  }
  return out;
}

/**
 * Strip trailing whitespace that is not backslash-escaped, per gitignore(5).
 */
function stripTrailingSpace(line: string): string {
  let end = line.length;
  while (end > 0 && (line[end - 1] === ' ' || line[end - 1] === '\t')) {
    // Count the backslashes directly before this whitespace run.
    let backslashes = 0;
    let k = end - 2;
    while (k >= 0 && line[k] === '\\') {
      backslashes++;
      k--;
    }
    if (backslashes % 2 === 1) break; // escaped — keep it
    end--;
  }
  return line.slice(0, end);
}

function compileRule(rawLine: string): Rule | null {
  let line = stripTrailingSpace(rawLine);
  if (line.length === 0) return null;
  if (line.startsWith('#')) return null;

  let negate = false;
  if (line.startsWith('!')) {
    negate = true;
    line = line.slice(1);
  } else if (line.startsWith('\\#') || line.startsWith('\\!')) {
    line = line.slice(1);
  }
  if (line.length === 0) return null;

  let dirOnly = false;
  if (line.endsWith('/') && !line.endsWith('\\/')) {
    dirOnly = true;
    line = line.slice(0, -1);
  }
  if (line.length === 0) return null;

  // Anchored when the pattern has a `/` anywhere other than the (already
  // removed) trailing one. A leading `/` anchors and is not part of the match.
  let anchored = line.includes('/');
  if (line.startsWith('/')) {
    anchored = true;
    line = line.slice(1);
  }
  if (line.length === 0) return null;
  // A leading `**/` explicitly means "at any depth" — it is translated as such
  // and must not also be root-anchored.
  const leadingGlobstar = line.startsWith('**/');

  const body = translateGlob(line);
  const prefix = anchored && !leadingGlobstar ? '^' : '^(?:.*/)?';
  try {
    return { re: new RegExp(`${prefix}${body}$`), negate, dirOnly, source: rawLine };
  } catch {
    return null;
  }
}

/** Build a matcher from raw `.gitignore`-syntax lines. */
export function compileGitignore(lines: readonly string[]): GitignoreMatcher {
  const rules: Rule[] = [];
  const invalid: string[] = [];

  for (const raw of lines) {
    const trimmedForClassification = stripTrailingSpace(raw);
    const isSkippable = trimmedForClassification.length === 0 || trimmedForClassification.startsWith('#');
    const rule = compileRule(raw);
    if (rule) rules.push(rule);
    else if (!isSkippable) invalid.push(raw);
  }

  function matchOne(candidate: string, isDir: boolean): boolean | null {
    let decision: boolean | null = null;
    for (const rule of rules) {
      if (rule.dirOnly && !isDir) continue;
      if (rule.re.test(candidate)) decision = !rule.negate;
    }
    return decision;
  }

  return {
    invalidPatterns: invalid,
    ignores(path: string, isDir = false): boolean {
      if (!path) return false;
      const clean = path.replace(/^\/+/, '').replace(/\/+$/, '');
      if (!clean) return false;
      const segments = clean.split('/');
      let ignored = false;
      for (let i = 0; i < segments.length; i++) {
        const candidate = segments.slice(0, i + 1).join('/');
        const candidateIsDir = i < segments.length - 1 || isDir;
        const decision = matchOne(candidate, candidateIsDir);
        if (decision !== null) ignored = decision;
      }
      return ignored;
    },
  };
}
